<?php require 'config.php'; if(logged_in()) go(); if (!(int)one('SELECT COUNT(*) n FROM users')['n']) go('setup.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_post(); $u=one('SELECT * FROM users WHERE username=?','s',[trim($_POST['username']??'')]); if($u && password_verify($_POST['password']??'',$u['password_hash'])) {session_regenerate_id(true); $_SESSION['user']=['id'=>$u['id'],'name'=>$u['full_name'],'role'=>$u['role']];go();} $error='Invalid username or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | ART CARE</title><link rel="stylesheet" href="style.css"></head><body class="auth"><div class="hero"><div class="brand">✦ ART CARE <small>DENTAL CARE CLINIC MANAGEMENT SYSTEM</small></div><small>WELCOME BACK</small><h1>A healthier smile starts here.</h1><p>Simple, organized, and reliable dental clinic scheduling.</p></div><main class="auth-form"><small>STAFF PORTAL</small><h1>Log in to your account</h1><p>Enter your username and password to continue.</p><?php if($error): ?><p class="error"><?=esc($error)?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button>Log in</button></form><p>New accounts are created by the administrator.</p></main></body></html>
